var n=`0403-full-english-breakfast`;var o=`world-0403`;var a=`GB`;var i=`northern-europe`;var s=4;var r=41;var u={en:`Full English Breakfast`,ua:`Повний англійський сніданок`};var d={en:`A traditional dish from United Kingdom, centered on bacon, fresh pork sausage, button mushroom, tomato. A measured home-kitchen version organized by cooking step. Baked beans are cooked from canned white beans and tomato in this home version.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: бекон, сира свиняча ковбаса, печериця, помідор. Домашній варіант із кількостями продуктів за етапами приготування. У домашньому варіанті запечену квасолю готують з консервованої білої квасолі й томатів.`};var g=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`bacon`,200,`g`],[`fresh-pork-sausage`,400,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`button-mushroom`,250,`g`],[`tomato`,350,`g`],[`unsalted-butter`,30,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 6 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 6 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:6,i:[[`chicken-egg`,4,`pcs`],[`sunflower-oil`,30,`ml`]]},{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`white-bread`,4,`slice`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`canned-white-beans`,350,`g`],[`tomato-passata`,150,`g`],[`white-granulated-sugar`,8,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[]}];var h={slug:n,id:o,country:`GB`,region:i,servings:4,minutes:41,title:u,text:d,steps:g};export{a as country,h as default,o as id,r as minutes,i as region,s as servings,n as slug,g as steps,d as text,u as title};